def apply(ns):
    """Merge into build.py's globals: slugs and texts of the new pages, the home section heading, the about description."""
    for pid, slugs in SLUGS.items():
        ns["SLUGS"][pid] = dict(slugs)
    for pid, langs in S.items():
        ns["S"][pid] = {l: dict(d) for l, d in langs.items()}
    for l, (title, text) in HOME_SECTORS.items():
        if l in ns["HOME"]:
            ns["HOME"][l]["sectors_title"], ns["HOME"][l]["sectors_text"] = title, text
    for l, desc in ABOUT_DESC.items():
        if l in ns["ABOUT"]:
            ns["ABOUT"][l]["desc"] = desc
